import { useEffect, useState, useRef, useCallback } from "react";
import { Button, Grid, MenuItem, Select, Typography } from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import TableClientCategory from "src/views/tables/TableClientCategory";
import DialogAddCategoryLogo from "src/views/dialog/DialogAddCategoryLogo";
import DialogFormClientCategory from "src/views/dialog/DialogFormClientCategory";

const ClientCategoryPage = () => {
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [clientData, setClientData] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState(" ");

  // Testimonials
  const [clientFormDialogOpen, setClientFormDialogOpen] = useState(false);
  const [clientFormDialogMode, setClientFormDialogMode] = useState("add");
  const [clientCategoryToEdit, setClientCategoryToEdit] = useState(null);
  const [addLogoDialogoOpen, setAddLogoDialogoOpen] = useState(false);
  const [addLogoDialogoMode, setAddLogoDialogoMode] = useState("add");

  const toggleRugFormDialog = (
    e,
    mode = "add",
    clientCategoryToEdit = null
  ) => {
    setClientFormDialogOpen((prev) => !prev);
    setClientFormDialogMode(mode);
    setClientCategoryToEdit(clientCategoryToEdit);
  };
  const toggleAddLogoDialog = (
    e,
    mode = "add",
    clientCategoryToEdit = null
  ) => {
    setAddLogoDialogoOpen((prev) => !prev);
    setAddLogoDialogoMode(mode);
    setClientCategoryToEdit(clientCategoryToEdit);
  };
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);
  const [testimonialToDelete, setTestimonialToDelete] = useState(null);

  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    setTestimonialToDelete(dataToDelete);
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ClientCategory.list, { params })
      .then((response) => {
        console.log(response.data.data);
        setClientData(response.data.data);
        setTotalCount(response.data.totalItems);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  //SEARCH
  useEffect(() => {
    if (!search) {
      // If search input is empty, show all data
      setClientData(clientData);
    } else {
      // Filter the contactData based on the search value
      const filtered = clientData.filter((item) =>
        item.category.toLowerCase().includes(search.toLowerCase())
      );
      setClientData(filtered); // Set the filtered data
    }
  }, [search, clientData]);

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      axiosInstance
        .delete(ApiEndPoints.ClientCategory.delete(testimonialToDelete.id))
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toggleConfirmationDialog();
          toastSuccess(response.message);
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
        });
    },
    [currentPage, testimonialToDelete, pageSize, search]
  );

  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text="Client Category " />
            </Typography>
          }
          action={
            <Button variant="contained" onClick={toggleRugFormDialog}>
              Add Categories
            </Button>
          }
        />
        <Grid item xs={12}>
          <Card>
            <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
                gap: 5,
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "all" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"all"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
              {/* <Box>
                <Button variant="contained" onClick={toggleAddLogoDialog}>
                  Add Logo
                </Button>
              </Box> */}
            </Box>
            <Box sx={{ p: 5 }}>
              <TableClientCategory
                status={status}
                search={search}
                loading={loading}
                rows={clientData}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                toggleDelete={toggleConfirmationDialog}
                toggleEdit={toggleRugFormDialog}
                toggleAddLogo={toggleAddLogoDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>

      <DialogFormClientCategory
        mode={clientFormDialogMode}
        open={clientFormDialogOpen}
        toggle={toggleRugFormDialog}
        dataToEdit={clientCategoryToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />

      <DialogAddCategoryLogo
        mode={addLogoDialogoMode}
        open={addLogoDialogoOpen}
        toggle={toggleAddLogoDialog}
        dataToEdit={clientCategoryToEdit}
        // onSuccess={() => {
        //   fetchData({
        //     currentPage: currentPage,
        //     pageSize: pageSize,
        //   });
        // }}
      />

      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete Client Category"
        subtitle="Are you sure you want to delete this Client Category?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />
    </>
  );
};

export default ClientCategoryPage;
